CREATE OR REPLACE FUNCTION calculate_fei(
    engrate_val numeric,
    socintscore_val numeric,
    actdayswk_val smallint,
    avgsesscount_val smallint
) RETURNS numeric AS $$
BEGIN
    RETURN (engrate_val * 0.4) + 
           (socintscore_val / 100.0 * 0.3) + 
           (actdayswk_val::numeric / 7.0 * 0.2) + 
           (avgsesscount_val::numeric / 10.0 * 0.1);
END;
$$ LANGUAGE plpgsql;
